from research_helpers import *
C=ev('https://www.caredx.com/science-innovation/products-solutions','Official issuer identifies transplant molecular tests; HeartCare combines AlloMap and AlloSure and is not counted as an additional underlying assay.')
A=ev('https://www.caredx.com/newsroom/press-releases/caredx-announces-second-quarter-2026-financial-results','Issuer confirms lab division sale closed June 30 2026, Naveris acquisition closed and AlloHeme/HistoMap still pipeline programs.')
P=ev('https://www.caredx.com/professionals/allosure-plus','AI-derived rejection-risk assessment tool; distinct from underlying dd-cfDNA assay.')
PH=ev('https://investors.caredx.com/news/news-details/2025/CareDx-Announces-New-Precision-Kidney-Transplant-Data-and-Product-Innovations-at-ASN-Kidney-Week-2025/default.aspx','Explicit AlloView rename to AlloSure Plus; HistoMap clinical-study availability does not prove unrestricted commercial launch.')
H=ev('https://www.caredx.com/science-innovation/pipeline/alloheme','Pipeline blood-based relapse monitoring assay for post-HCT AML/MDS.')
D=ev('https://investors.caredx.com/files/doc_events/2025/06/1/Jefferies-Presentation.pdf','Issuer names AlloMap Kidney gene-expression test and UroMap urine test; current commercialization status not assumed from plans.')
N=ev('https://www.caredx.com/newsroom/press-releases/caredx-completes-acquisition-of-naveris-extending-leadership-into-high-growth-specialty-oncology','July 1 2026 completed acquisition; NavDx commercially reported tests. CareDx owner role, no original inventor claim.')
V=ev('https://www.caredx.com/newsroom/press-releases/caredx-announces-vantx-tm-an-ai-powered-clinical-data-and-analytics-platform','March 2026 launched transplant research analytics platform with consultation-based access; self-service future plan not assumed completed.')
ps=[]
for n,organ,url in [('AlloSure Kidney','kidney','https://www.caredx.com/professionals/allosure-kidney'),('AlloSure Heart','heart','https://www.caredx.com/science-innovation/products-solutions'),('AlloSure Lung','lung','https://www.caredx.com/professionals/allosure-lung')]:
 e=ev(url,'Official organ-specific commercial molecular test offering; not a trial name. Detailed assay differences and shared core methods require further reconciliation.')
 ps.append(p(n,f'Donor-derived cell-free DNA transplant monitoring test for {organ} recipients.',e,'commercial',typ='product',sub='diagnostics'))
ps += [p('AlloMap Heart','Gene-expression profiling test for heart transplant surveillance.',C,'commercial',typ='product',sub='diagnostics'),p('AlloSure Plus','AI-derived kidney transplant rejection risk assessment tool.',P,'commercial',aliases=['AlloView'],typ='product',sub='diagnostics',evidence=[P,PH]),p('AlloMap Kidney','Gene-expression profiling test for kidney transplant risk assessment.',D,sub='diagnostics'),p('HistoMap Kidney','Tissue gene-expression assay for transplant biopsy assessment.',PH,'development',sub='diagnostics',evidence=[PH,A]),p('UroMap','Urine-based transplant monitoring test for BK virus-related assessment.',D,sub='diagnostics'),p('AlloHeme','Blood-based relapse monitoring test following hematopoietic cell transplant.',H,'development',sub='diagnostics',evidence=[H,A]),p('NavDx','Blood-based assay for monitoring viral-mediated cancers.',N,'commercial',roles=['owner'],valid_from='2026-07-01',typ='product',sub='diagnostics'),p('VANTx','Clinical data and analytics platform for transplant research.',V,'commercial',typ='product',sub='research_software')]
for n,slug,d in [('AlloSeq Tx','alloseq-tx','NGS-based HLA typing assay.'),('AlloSeq HCT','alloseq-hct','NGS-based transplant chimerism assay.'),('AlloSeq cfDNA','alloseq-cfdna','Donor-derived cell-free DNA transplant surveillance kit.'),('QTYPE','qtype','Real-time PCR HLA typing assay.'),('Olerup SSP','olerup-ssp','Sequence-specific primer HLA typing kit portfolio.')]:
 e=ev('https://labproducts.gendx.com/products/'+slug,'Current successor product page confirms exact assay identity; historical CareDx lab division relationship ended with June 30 2026 sale. Local regulatory/RUO conditions are not universal diagnostic approval.')
 ps.append(p(n,d,e,'commercial',roles=['owner'],valid_to='2026-06-30',typ='product',sub='diagnostics',evidence=[e,A]))
NN=ev('https://www.caredx.com/newsroom/press-releases/caredx-introduces-alloseq-nano-at-efi-2026-expanding-hla-typing-portfolio-with-long-read-sequencing','April 2026 issuer introduced AlloSeq Nano and identifies it as part of lab division subject to divestiture; early-access status not confused with unrestricted approval.')
ps.append(p('AlloSeq Nano','Nanopore-based HLA and ABO genotyping assay.',NN,'commercial',roles=['developer'],typ='product',sub='diagnostics',evidence=[NN,A],attributes={'historical_commercial_access':'early_access','lab_division_sold_at':'2026-06-30'}))
TR=ev('https://labproducts.gendx.com/products/trusight-hla','Explicit CareDx exclusive global license and distribution agreement with Illumina for TruSight HLA assays and Assign software. CareDx not recorded original developer.')
ps.append(p('TruSight HLA','NGS HLA typing assay portfolio.',TR,'commercial',roles=['licensee','commercial_partner'],valid_to='2026-06-30',typ='product',sub='diagnostics',evidence=[TR,A]))
companies=[company('Caredx Inc',ps,[C,A,P,PH,H,D,N,V,NN,TR],'Commercial transplant tests, named pipeline assays, Naveris acquisition and historical sold lab division reviewed. AlloSure organ-specific test identity, AlloSeq Tx subvariants, Olerup/SCORE/Assign legacy kits/software, AlloCell, digital workflow applications and current assay rights/regulatory contexts require follow-up. HeartCare/KidneyCare bundled offerings not automatically counted as extra assays.')]
(out/'batch-0023.json').write_text(json.dumps({'companies':companies},indent=2))
